{"command": "cd data && (
  awk -F',' 'NR>1 { if ($4 == "" || $4 == " ") print $1 }' events.csv
  awk -F',' 'NR>1 { if ($4+0 < 0) print $1 }' events.csv
  awk -F',' 'NR>1 { if ($4+0 > 10000) print $1 }' events.csv
  awk -F',' 'NR>1 { if ($5 != "grocery" && $5 != "travel" && $5 != "salary" && $5 != "rent" && $5 != "other") print $1 }' events.csv
) | sort -u"}

{"command": "cd data && awk -F',' 'NR>1 {
  amount = $4
  category = $5
  if (amount != "" && amount+0 >= 0 && amount+0 <= 10000 && (category == "grocery" || category == "travel" || category == "salary" || category == "rent" || category == "other")) {
    print $0
  }
}' events.csv >> /tmp/events_filtered.csv"}

